seq="".join(l.strip() for l in open("region.fasta") if not l.startswith(">"))
L=len(seq)
# self-similarity: compare all 25-mers with <=3 mismatches, report pairs far apart
k=25
hits=[]
for i in range(L-k+1):
    for j in range(i+40, L-k+1):
        mm=0
        for a,b in zip(seq[i:i+k],seq[j:j+k]):
            if a!=b:
                mm+=1
                if mm>3: break
        if mm<=3:
            hits.append((i+1,j+1,mm))
# cluster
print("self-similar 25-mer pairs (<=3 mismatches), distance>40:")
for i,j,mm in hits[:60]:
    print("  %d vs %d (mm=%d) %s | %s"%(i,j,mm,seq[i-1:i-1+k],seq[j-1:j-1+k]))
print("total:",len(hits))
